const steps={
 lobby:['Before puck drop','Keep the QR on the big screen. Open the first five calls at the horn.','Open first intermission','break1'],
 break1:['First break · picks open','Closing this round locks all first-period picks and switches the big screen to the leaders.','Close round 1 & show leaders','leaders1'],
 leaders1:['First-intermission leaders','Leave this board up during period two. At the next horn, reopen the same QR for five new duels.','Open second intermission','break2'],
 break2:['Second break · picks open','Close voting to show the combined scores from both breaks.','Close round 2 & show leaders','leaders2'],
 leaders2:['Second-intermission leaders','Keep the combined standings up until the final horn.','Show final winners','final'],
 final:['Final horn','Among the top combined scorers who finished both rounds, draw one prize winner. A tied leader gets the same chance as any other tied leader.','Draw prize winner','draw']
};
const esc=x=>String(x??'').replace(/[&<>"']/g,v=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[v]));
export function mountHost(root,client){
 let alive=true,interval,latest,working=false,ask=null,secret='',notice='',staged=null;
 root.innerHTML=`<main class="event-host"><div class="host-top"><b>OT / EVENT DESK</b><span>${client.mode==='demo'?'REHEARSAL':'SHARED EVENT'}</span></div><h1>Game control.</h1><p class="host-help">${client.mode==='demo'?'Use separate tabs in this browser as the phone and scoreboard. Other devices have independent rehearsals.':'Fans use one QR for the whole match. Only the operator can change stages.'}</p><nav class="host-links"><a href="#screen" target="_blank" rel="noopener">Open scoreboard ↗</a><a href="#play" target="_blank" rel="noopener">Open fan view ↗</a></nav>${client.mode==='live'?'<label>Operator key<input class="host-input" type="password" autocomplete="off" placeholder="Enter event operator key"></label>':''}<div class="host-current" aria-live="polite"></div>${client.mode==='live'?`<details class="host-fixture host-card"><summary>Load verified period data</summary><p>Choose the five comparisons for the period that just ended. Only load data approved for display to arena fans. Once you open the break, its answers are frozen.</p><input type="file" accept="application/json,.json" aria-label="Period comparison file"><p class="pack-info"></p><button class="host-btn alt" type="button" data-upload disabled>Load this period</button></details>`:''}<form class="host-claim" hidden><label>Verify winner’s private code<input class="host-input" name="code" autocomplete="off" maxlength="16" required></label><button class="host-btn alt" type="submit">Check code</button></form><p class="host-status" role="status"></p></main>`;
 const panel=root.querySelector('.host-current'),status=root.querySelector('.host-status');const input=root.querySelector('input');if(input)input.oninput=()=>secret=input.value.trim();
 function draw(s){
  root.querySelector('.host-claim').hidden=!s.draw;const pack=root.querySelector('.host-fixture');if(pack){pack.hidden=!['lobby','leaders1'].includes(s.stage);if(staged&&staged.stage!==s.stage){staged=null;pack.querySelector('button').disabled=true;pack.querySelector('.pack-info').textContent='';pack.querySelector('input').value='';}}const row=steps[s.stage];if(!row)return;
  const key=[s.stage,s.joined,s.completed,s.finishers,s.eligible,s.draw?.alias,JSON.stringify(s.loadedPeriods||[]),ask,working].join(':');if(panel.dataset.state===key)return;panel.dataset.state=key;
  panel.innerHTML=`<section class="host-card"><small class="host-chip">CURRENT STAGE</small><h2>${row[0]}</h2><p>${row[1]}</p>${client.mode==='live'&&['lobby','leaders1'].includes(s.stage)?'<p>Next break data: <b>'+((s.loadedPeriods||[]).includes(s.stage==='lobby'?1:2)?'operator-supplied and ready':esc(client.fixtureLabel))+'</b></p>':''}<p class="host-metrics"><span><b>${Number(s.joined)}</b> joined</span><span><b>${Number(s.completed)}</b> finished this break</span><span><b>${Number(s.finishers)}</b> finished both</span><span><b>${Number(s.eligible)}</b> draw-eligible leaders</span></p>${s.draw?'<p>Prize winner: <strong>'+esc(s.draw.alias)+'</strong></p>':''}${ask?`<p>${ask==='reset'?'Clear the rehearsal scores and return to the first break?':row[2]+' now?'}</p><button class="host-btn" data-host="confirm" ${working?'disabled':''}>Confirm</button> <button class="host-btn alt" data-host="cancel">Cancel</button>`:`<button class="host-btn" data-host="next" ${working||s.draw||s.stage==='final'&&!s.eligible?'disabled':''}>${row[2]}</button>`}</section>${client.mode==='demo'&&!ask?'<button class="host-btn alt" data-host="reset">Start a fresh rehearsal</button>':''}`;
 }
 async function refresh(){if(working)return;try{const s=await client.publicStatus();if(!alive||working)return;if(latest&&s.stage!==latest.stage)ask=null;latest=s;draw(s);status.textContent=notice;}catch{if(alive)status.textContent='Connection lost. Waiting for the arena…';}}
 const click=async e=>{const action=e.target.closest('[data-host]')?.dataset.host;if(!latest||!action||working)return;
 if(action==='next'||action==='reset'){if(client.mode==='live'&&!secret){status.textContent='Enter the operator key first.';input?.focus();return;}ask=action;draw(latest);return;}
 if(action==='cancel'){ask=null;draw(latest);return;}if(action!=='confirm'||!ask)return;
 const next=steps[latest.stage][3],op=ask==='reset'?'reset-demo':next==='draw'?'draw':'advance';working=true;draw(latest);
 try{latest=await client.hostCall(op,op==='advance'?{to:next}:{},secret);notice='Scoreboard updated.';}catch(err){notice=err.message||'Unable to update the stage.';}finally{working=false;ask=null;if(alive){draw(latest);status.textContent=notice;}}};
 const pack=root.querySelector('.host-fixture');if(pack){const picker=pack.querySelector('input'),up=pack.querySelector('button'),info=pack.querySelector('.pack-info');picker.onchange=async()=>{staged=null;up.disabled=true;try{const file=picker.files[0];if(!file)return;if(file.size>60000)throw Error('Maximum file size is 60 KB.');const f=JSON.parse(await file.text());if(!Array.isArray(f.players)||!Array.isArray(f.round)||f.round.length!==5)throw Error('Expected players plus a round of five comparisons.');staged={fixture:f,stage:latest.stage,period:latest.stage==='lobby'?1:2};info.textContent='Ready to load period '+staged.period+': '+f.players.length+' players, 5 duels.';up.disabled=false;}catch(err){info.textContent=err.message;}};up.onclick=async()=>{if(!staged||working||staged.stage!==latest.stage)return;working=true;up.disabled=true;try{latest=await client.hostCall('loadPeriod',{period:staged.period,fixture:staged.fixture},secret);notice='Period '+staged.period+' verified and ready.';staged=null;picker.value='';info.textContent='';}catch(err){notice=err.message;up.disabled=false;}finally{working=false;if(alive){draw(latest);status.textContent=notice;}}};}
 root.querySelector('.host-claim').onsubmit=async e=>{e.preventDefault();try{const result=await client.hostCall('verifyClaim',{code:e.target.elements.code.value.trim()},secret);notice=result.claimVerified?'Verified: this fan holds the winning pass.':'Code does not match the winning pass.';}catch(err){notice=err.message;}if(alive)status.textContent=notice;};root.addEventListener('click',click);refresh();interval=setInterval(refresh,2300);return()=>{alive=false;clearInterval(interval);root.removeEventListener('click',click);};
}
